    const f = F * r, dt = Math.max(1, Math.round(f * 0.011)) / f;
    for (let j = 0; j * dt < H + L - 1e-9; j++){
      const u = j * dt, a = k * (u < H ? g * Math.pow(10, -1.7 * (1 - u / H)) : lv(u - H));
      this._tone(t + u, { freq: f, gain: a, dur: D, type:"sine" }).frequency.value = f;
